INSERT INTO regle_magie (id, titre, niveau_sort, texte, origine, source_ref) VALUES ('magies#regle:regle-speciale-pour-sort-niveau-5', 'Règle spéciale pour sort niveau 5', 5, 'Règle spéciale pour sort niveau 5 : Les sorts sont si puissant qu''il demande un tour de charge pour être lancé. Donc on le charge avec l''action du premier tour et l''action du tour suivant sert à lancer le sort mais pas besoin de faire 2 jets de magie pour lancer le sort, celui du premier tour est pris en compte. Si jamais un ennemi attaque et touche, un jet de concentration est nécessaire pour ne pas perdre la charge du sort (perdre la charge du sort n''annule pas l''action du prochain tour mais perdra la moitié du coût en chakra). Pendant ce temps, le lanceur peut se défendre si il a une posture qui le permet, se déplacer et même changer de posture le tour 2 avant de lancer son sort mais il est sera contraint de lancer le sort (donc pas d''IC le tour 2 si le sort n''est pas interrompu).', 'magies', 'Magie Maverick V8 › Sommaire › A31');
